<?php require_once __DIR__.'/bootstrap.php'; $p=db();
$p->exec("CREATE TABLE IF NOT EXISTS noora_admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS noora_articles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,excerpt TEXT,body MEDIUMTEXT,image_url VARCHAR(1000),category VARCHAR(120),status ENUM('draft','published') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$exists=(int)$p->query('SELECT COUNT(*) FROM noora_admins')->fetchColumn()>0;$err='';$ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'&&!$exists){check_token();$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$pw=$_POST['password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<12)$err='نام و ایمیل معتبر و رمز حداقل ۱۲ کاراکتری وارد کنید.';else{$q=$p->prepare('INSERT INTO noora_admins(name,email,password_hash) VALUES(?,?,?)');$q->execute([$n,$e,password_hash($pw,PASSWORD_DEFAULT)]);$ok=true;$exists=true;}}
?><!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>راه‌اندازی NOORA</title><link rel="stylesheet" href="admin.css"><body class="login"><section class="card"><b class="logo">NOORA<span>.</span></b><h1>راه‌اندازی پنل مدیریت</h1><?php if($ok):?><p class="success">حساب مدیر ساخته شد. اکنون فایل install.php را از هاست حذف کنید.</p><a class="btn" href="login.php">ورود به پنل ←</a><?php elseif($exists):?><p class="notice">مدیر قبلاً ساخته شده است. فایل install.php را حذف کنید.</p><a class="btn" href="login.php">ورود به پنل ←</a><?php else:?><?php if($err)echo '<p class="error">'.h($err).'</p>';?><p>برای ساخت اولین حساب مدیر، فرم را تکمیل کنید.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><label>نام مدیر</label><input name="name" required maxlength="120"><label>ایمیل</label><input type="email" name="email" required maxlength="190"><label>رمز قوی (حداقل ۱۲ کاراکتر)</label><input type="password" name="password" required minlength="12"><button class="btn">ساخت حساب مدیر ←</button></form><?php endif;?></section></body></html>
